// Nodo "Configuración" del flujo "Secretaria · Limpieza de eventos": lo que se toca a mano está aquí.
// Los demás nodos leen estos valores con $('Configuración').first().json.config

// Los identificadores (no son secretos) se leen del .env del servidor, así se ponen UNA vez para todos los flujos.
// Si una variable no está en el .env, vale lo que esté escrito aquí abajo.
const delEntorno = (clave, porDefecto) => {
  try {
    return String($env[clave] ?? '').trim() || porDefecto;
  } catch (e) {
    return porDefecto;
  }
};

// === Valores fáciles de cambiar ===
// Project URL de Supabase (Integrations > Data API), sin /rest/v1 al final. No es un secreto.
const SUPABASE_URL = delEntorno('SUPABASE_URL', 'https://TU-PROYECTO.supabase.co');
// Días que pasan, desde que TERMINA un evento, antes de archivarlo. Al archivarlo, el flujo "Sincronizar Calendar" borra su evento de
// Google Calendar (Google lo conserva unos 30 días en su papelera). El item queda en la base de datos como "archivado".
const DIAS_RETENCION = 7;
// Máximo de eventos que se archivan en cada pasada (una al día). Si hay más (la primera vez, con eventos antiguos acumulados), el resto
// sigue en las pasadas siguientes.
const LOTE = 50;
// ==================================

if (!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(SUPABASE_URL) || SUPABASE_URL.includes('TU-PROYECTO')) {
  throw new Error('Configuración: pon tu Project URL de Supabase en SUPABASE_URL (https://<ref>.supabase.co, sin /rest/v1). Va en el .env del servidor (SUPABASE_URL=…, y después docker compose up -d)');
}
if (!Number.isFinite(DIAS_RETENCION) || DIAS_RETENCION < 1 || DIAS_RETENCION > 365) {
  throw new Error('Configuración: DIAS_RETENCION debe estar entre 1 y 365');
}
if (!Number.isInteger(LOTE) || LOTE < 1 || LOTE > 200) {
  throw new Error('Configuración: LOTE debe estar entre 1 y 200');
}

return [{ json: { config: { supabase_url: SUPABASE_URL.replace(/\/+$/, ''), dias_retencion: DIAS_RETENCION, lote: LOTE } } }];

// Nodo "Calcular límite": fija la fecha límite (ahora menos DIAS_RETENCION días) y construye la URL de la consulta de eventos antiguos.
// Un evento es antiguo si su FIN pasó antes del límite; si no tiene fin, cuenta su inicio. Solo eventos en estado pendiente o hecho
// (los archivados ya los trata el flujo de Calendar). Los más antiguos primero, y como mucho LOTE.

const config = $('Configuración').first().json.config;
const limite = new Date(Date.now() - config.dias_retencion * 86400000).toISOString();

const filtroFecha = `(fecha_fin.lt."${limite}",and(fecha_fin.is.null,fecha_inicio.lt."${limite}"))`;
const url = `${config.supabase_url}/rest/v1/items?select=id,titulo,fecha_inicio,fecha_fin,estado&tipo=eq.evento&estado=in.(pendiente,hecho)&or=${encodeURIComponent(filtroFecha)}&order=fecha_inicio.asc&limit=${config.lote}`;

return [{ json: { limite, url_lectura: url } }];

// Nodo "Planificar archivado": convierte los eventos antiguos que devolvió Supabase en UNA petición que los archiva.
//
// Doble comprobación: la consulta ya filtra por fecha, pero aquí se vuelve a comprobar cada fila (tipo evento, estado pendiente u hecho,
// id válido y fecha realmente anterior al límite) antes de archivar nada. Así un filtro mal construido nunca puede archivar un evento
// de hoy o futuro. Si no queda ninguno devuelve [] y el flujo termina.
// El PATCH repite las condiciones de tipo y estado: un item que cambió entre la lectura y la escritura no se toca.

const config = $('Configuración').first().json.config;
const limite = Date.parse($('Calcular límite').first().json.limite);
if (Number.isNaN(limite)) throw new Error('Planificar archivado: el límite de fecha no es válido');

const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const antes = (s) => typeof s === 'string' && !Number.isNaN(Date.parse(s)) && Date.parse(s) < limite;

const filas = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && typeof r.id === 'string' && ID.test(r.id) && ['pendiente', 'hecho'].includes(r.estado) && (r.fecha_fin != null ? antes(r.fecha_fin) : antes(r.fecha_inicio)));

if (filas.length === 0) return [];

return [
  {
    json: {
      etiqueta: `archivar ${filas.length} evento(s) pasado(s)`,
      url: `${config.supabase_url}/rest/v1/items?id=in.(${filas.map((f) => f.id).join(',')})&tipo=eq.evento&estado=in.(pendiente,hecho)&select=id,titulo`,
      cuerpo: { estado: 'archivado' },
      planificados: filas.length,
    },
  },
];

// Nodo "Resumen": deja constancia de cuántos eventos se archivaron (se ve en el historial de ejecuciones). Los eventos archivados dejan
// de existir en Google Calendar en los minutos siguientes: el flujo "Sincronizar Calendar" borra el evento de todo item archivado.

const planificados = $('Planificar archivado').first().json.planificados;
const archivados = $input.all().map((i) => i.json).filter((r) => r && typeof r.id === 'string');

return [
  {
    json: {
      planificados,
      archivados: archivados.length,
      // Los que cambiaron entre la lectura y la escritura no se tocan: solo se informa
      sin_tocar: Math.max(0, planificados - archivados.length),
      titulos: archivados.map((r) => String(r.titulo ?? '').slice(0, 60)),
    },
  },
];
